import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
refs = json.loads(Path('reference-targets.json').read_text())
answers = {}

def add(number, text, reason, notes, benefit=None, removed=None, repeal=None):
    s = next(a for a in sources if a['number'] == number)
    a = {k: s[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    a.update(proposed_xml='\n'.join('<p>'+p.strip()+'</p>' for p in text.strip().split('\n') if p.strip()),
             reason=reason, review_notes=notes, status='rewrite_draft')
    if benefit:
        a['benefit_review'] = benefit
    if removed:
        a.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    if repeal:
        a.update(change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19', repeal_scope=repeal)
    answers[number] = a

add('L233-1', '''Les organismes mentionnés aux articles L. 211-1, L. 213-1, L. 215-1, L. 221-1, L. 222-1, L. 225-1 et L. 752-4 coordonnent les missions qu'ils exercent auprès des travailleurs indépendants afin :<br/>1° D'assurer, lorsque leurs activités le nécessitent, leur bonne articulation entre les organismes mentionnés aux articles L. 211-1, L. 213-1, L. 215-1 et L. 752-4. Cette coordination porte notamment sur l'accueil et l'accompagnement dédiés des assurés, la réception de leurs demandes, l'instruction de leurs demandes d'action sociale ainsi que l'enregistrement et la fiabilisation des droits futurs ouverts par le paiement de leurs cotisations ;<br/>2° D'assurer l'atteinte des objectifs de qualité de service fixés, pour ces assurés, par les conventions mentionnées à l'article L. 227-1.
Le directeur général de la caisse mentionnée à l'article L. 221-1 et les directeurs des organismes mentionnés aux articles L. 222-1 et L. 225-1 assurent conjointement cette coordination. Elle ne requiert ni schéma stratégique d'organisation distinct ni approbation des ministres chargés de la sécurité sociale et du budget.
La suppression du schéma obligatoire et de son approbation s'applique dès l'entrée en vigueur de la loi, sans nouvelle formalité pour les travaux en cours. Elle ne suspend aucun service aux assurés et ne remet pas en cause les droits ni les engagements valablement constitués.''',
    "Réforme de fond : suppression du schéma stratégique distinct et de son approbation ministérielle, qui ajoutent une procédure à la coordination opérationnelle et aux objectifs des conventions existantes. Réécriture des deux finalités à droit constant : accueil, action sociale et fiabilisation des droits des indépendants sont maintenus.",
    "Coordonner les textes d'application imposant ce schéma ou son approbation, sans document de remplacement. Les compétences des organismes et les conventions de L227-1 subsistent. Le dispositif concerne les indépendants, sans condition liée au contrat unique ni à l'ancienneté du salarié.",
    removed=["Établissement obligatoire d'un schéma stratégique d'organisation distinct pour les missions auprès des indépendants.", "Approbation du schéma par les ministres chargés de la sécurité sociale et du budget, sans déclaration de remplacement."])

add('L241-2', '''I. – Les dépenses de prise en charge des frais de santé mentionnés à l'article L. 160-1, des prestations mentionnées aux titres II à IV et VI du livre III, des frais de gestion et des autres charges de la branche maladie sont couvertes par les cotisations, contributions et autres ressources énumérées aux II à IV. La Caisse nationale de l'assurance maladie centralise ces ressources et enregistre l'ensemble des opérations correspondantes.
II. – Dans chacun des régimes, les ressources mentionnées au I comprennent les cotisations acquittées :
1° Par les employeurs des professions agricoles et non agricoles ;
2° Par les travailleurs indépendants des professions non agricoles et les personnes non salariées des professions agricoles ;
3° Par les personnes mentionnées aux articles L. 380-2 et L. 380-3-1 ;
4° Par les personnes mentionnées à l'article L. 131-9.
III. – Ces ressources comprennent également les cotisations assises sur les revenus mentionnés à l'article L. 131-2.
IV. – Les ressources des assurances maladie, maternité, invalidité et décès comprennent en outre les impositions et remboursements suivants, attribués à la branche Maladie, maternité, invalidité et décès du régime général :
1° Le produit des impôts et taxes mentionnés à l'article L. 131-8, dans les conditions fixées par cet article ;
2° Le remboursement effectué par la Caisse nationale des allocations familiales, à hauteur des montants fixés au 6° de l'article L. 223-1 ;
3° La fraction de taxe sur la valeur ajoutée attribuée dans les conditions de l'article L. 131-8 ;
4° Abrogé ;
5° Une fraction des prélèvements sur les jeux et paris prévus aux articles L. 137-20, L. 137-21 et L. 137-22 ;
6° Les contributions prévues aux articles L. 245-1, L. 245-5-1 et L. 245-6 ;
7° Les droits perçus au titre des articles 1635 bis AE, 1635 bis AF, 1635 bis AG et 1635 bis AH du code général des impôts et de l'article L. 5321-3 du code de la santé publique ;
8° Le produit de la taxe perçue au titre des contrats mentionnés au II de l'article L. 862-4, dans les conditions fixées par l'arrêté mentionné au 8° de l'article L. 131-8 ;
9° La fraction du produit de la contribution sociale généralisée mentionnée au b du 3° de l'article L. 131-8 ;
10° Le produit de la contribution mentionnée à l'article L. 862-4-1.''',
    "Réécriture à droit constant des dépenses et des dix rubriques de financement, avec des sujets explicites. L'article centralise des ressources affectées à la couverture maladie ; retirer une ligne d'affectation ne supprimerait pas le prélèvement institué ailleurs. Aucune cotisation de couverture essentielle n'est abolie sans disposition d'assiette et de financement correspondante.",
    "Conserver l'application aux prestations dues depuis le 1er janvier 2023 indiquée par la note source. L223-1, 6°, distingue 60 %, remboursement intégral et frais de gestion ; aucune indemnité de congé n'est supprimée. L131-8 proposé coordonne la CSG privée financée sans modifier les autres revenus. L623-1 inclut la réserve QPC du 8 août 2025 pour la filiation par reconnaissance conjointe ; le renvoi financier ne la restreint pas. Les droits sanitaires du IV, 7°, sont des fondements extérieurs non réécrits ici. Aucun renvoi de financement ne recrée un prélèvement supprimé à son article d'origine.")

add('L241-3-1', '''Par dérogation à l'article L. 241-3, l'assiette des cotisations d'assurance vieillesse peut être maintenue au niveau du salaire correspondant à l'activité exercée à temps plein lorsque l'emploi est exercé à temps partiel au sens de l'article L. 3123-1 du code du travail. Cette faculté s'applique également, dans les conditions fixées par décret, aux emplois dont la rémunération ne peut pas être déterminée d'après un nombre d'heures travaillées. La part salariale prise en charge par l'employeur est exclue de l'assiette de la contribution prévue à l'article L. 136-1. Les conditions dans lesquelles les employeurs peuvent exercer cette faculté sont fixées par décret en Conseil d'Etat. Le taux des cotisations est fixé par décret en Conseil d'Etat.''',
    "Réécriture à droit constant d'une faculté favorable de maintien de l'assiette vieillesse à temps plein. La distinction entre temps partiel et rémunération non horaire ainsi que l'exclusion de CSG de la part salariale prise en charge par l'employeur sont explicitées. Supprimer cette faculté ou la rendre obligatoire réduirait l'avantage ou augmenterait les charges.",
    "La note source vise les périodes courant depuis le 1er septembre 2018. Ne pas confondre cette assiette volontaire avec le transfert futur de cotisations de L241-3 proposé : son premier champ est le salariat privé du régime général et il reste limité aux cotisations effectivement dues. Aucun transfert ni financement n'est déclaré déjà réalisé. Le renvoi à L3123-1 ne relève pas automatiquement les références annuelles à 1607 heures.",
    benefit="Le maintien volontaire d'une assiette vieillesse correspondant au temps plein reste ouvert aux futurs emplois à temps partiel et aux emplois non horaires éligibles. L'exclusion de CSG de la part salariale supportée par l'employeur est conservée sans limitation nouvelle ; ni le contrat unique ni son ancienneté n'en ferment le bénéfice.")

add('L241-3-2', '''Par dérogation à l'article L. 241-3, lorsque le contrat de travail est suspendu au titre d'un congé parental d'éducation prévu à l'article L. 1225-47 du code du travail, d'un congé de solidarité familiale mentionné à l'article L. 3142-6 du même code, d'un congé de proche aidant mentionné à son article L. 3142-16 ou d'un congé de présence parentale prévu à son article L. 1225-62, l'employeur et le salarié peuvent verser des cotisations ou contributions aux régimes de retraite complémentaire mentionnés au b du 2° du III de l'article L. 136-1-1 du présent code. Les conditions de ces versements sont déterminées par accord collectif. La part salariale prise en charge par l'employeur est exclue de l'assiette de la contribution prévue à l'article L. 136-1 pendant toute la durée de cette prise en charge au cours du congé.
La suppression de la limite de six mois d'exclusion s'applique aux prises en charge afférentes aux périodes courant à compter de l'entrée en vigueur de la loi, y compris pour les congés en cours. Les périodes antérieures, leurs exclusions, créances, restitutions et recours demeurent régis par les règles qui leur étaient applicables.''',
    "Réforme de fond : retrait de la limite de six mois de l'exclusion de CSG sur la part salariale de retraite complémentaire prise en charge pendant les quatre congés. La poursuite facultative des versements selon accord collectif et les quatre motifs de suspension sont conservés et réécrits clairement.",
    "Coordonner les textes de paie et d'application de la limite de six mois avec L136-1-1, III, 2°, d), qui renvoie déjà aux conditions du présent article. L136-1-1, III, 2°, b), vise les régimes complémentaires ; L241-3 proposé ne transforme pas ces versements en transfert obligatoire. La note source de 2018 n'est pas la date d'effet de l'extension nouvelle. Les quatre articles de congé ne sont pas des règles de rupture.",
    benefit="L'accord collectif peut toujours permettre le maintien des cotisations de retraite complémentaire pendant chacun des quatre congés énumérés. L'exclusion de CSG de la part salariale prise en charge par l'employeur est élargie au-delà des six premiers mois pour toutes les futures périodes éligibles, y compris dans les congés déjà commencés, sans supprimer les exclusions antérieures.",
    removed=["Limitation aux six premiers mois du congé de l'exclusion de CSG de la part salariale prise en charge par l'employeur."])

add('L241-3-3', '''Le présent article est abrogé à compter de l'entrée en vigueur de la loi.
Aucun malus sur les cotisations patronales d'assurance vieillesse ou d'assurance veuvage ne peut être dû sur le fondement du présent article pour les périodes de cotisation courant à compter de cette date, même si le défaut de négociation ou de plan d'action est antérieur. Aucun prélèvement ni formalité de remplacement n'est institué.
Les sommes légalement dues au titre des périodes antérieures, leurs régularisations, recouvrements, restitutions, prescriptions et recours demeurent régis par les dispositions alors applicables, sous réserve de l'application de la loi répressive plus douce aux sanctions non définitives. Les obligations de négociation ayant un fondement distinct ne sont pas supprimées par cette abrogation.''',
    "Réforme de fond : abolition du malus vieillesse et veuvage frappant les entreprises d'au moins trois cents salariés en cas de défaut de négociation ou de plan pour les salariés expérimentés. Cette surtaxe ne constitue pas une garantie de santé ou un droit individuel à conserver ; les obligations de négociation autonomes et le recours au juge subsistent.",
    "Retirer les barèmes et circuits réglementaires propres à ce malus. Coordonner L2242-2-1 du code du travail sans prétendre en avoir supprimé les obligations de négociation. La note d'entrée en vigueur immédiate de la loi du 30 décembre 2025 ne date pas la réforme proposée. Distinguer les périodes anciennes des faits nouveaux et contrôler le caractère répressif des créances anciennes pour la loi plus douce.",
    repeal="Suppression prospective de l'intégralité du malus patronal vieillesse et veuvage lié au défaut de négociation ou de plan annuel sur les salariés expérimentés, sans prélèvement substitutif.")

add('L241-5', '''Les employeurs supportent seuls les cotisations dues au titre des accidents du travail et des maladies professionnelles. Leur assiette est constituée des revenus d'activité des salariés retenus pour les cotisations définies à l'article L. 242-1.
Ces cotisations ne peuvent être totalement exonérées, même pour une fraction seulement de la rémunération. Les réductions prévues au III de l'article L. 241-10 et à l'article L. 241-13 peuvent s'imputer sur ces cotisations, dans la limite d'un taux fixé par arrêté ministériel qui ne peut dépasser celui applicable à une entreprise où aucun accident du travail ni aucune maladie professionnelle n'est jamais survenu.
La branche Accidents du travail et maladies professionnelles reçoit également le produit de la pénalité prévue à l'article L. 4163-2 du code du travail.''',
    "Réécriture à droit constant : responsabilité exclusive de l'employeur, assiette, limite d'imputation des réductions et ressource complémentaire sont présentées séparément. Le financement de la réparation et la responsabilisation liée au risque professionnel ont une fonction essentielle ; leur suppression compromettrait la protection des victimes. Les réductions existantes ne sont pas supprimées.",
    "Conserver la seconde phrase du deuxième alinéa comme cible de L241-10 et L241-13 : l'arrêté et son plafond restent au même emplacement. Le produit de L4163-2 relève de la prévention des risques et n'est pas le malus seniors de L241-3-3. L242-1 réécrit conserve l'assiette d'activité et ses exclusions ; aucune cotisation AT-MP n'est transférée au salarié.",
    benefit="L'imputation des réductions d'aide à domicile de L241-10, III, et de la réduction générale de L241-13 sur les cotisations AT-MP reste applicable aux futures rémunérations éligibles, au taux réglementaire plafonné par le risque minimal. L'absence d'exonération totale demeure une règle de financement des accidents ; elle ne supprime aucun des deux allègements autorisés.")

add('L241-5-1', '''Pour tenir compte des risques particuliers auxquels sont exposés les salariés des entreprises de travail temporaire mis à disposition d'utilisateurs, une partie du coût de l'accident ou de la maladie professionnelle définis aux articles L. 411-1 et L. 461-1 est supportée par l'entreprise utilisatrice si elle est soumise, à la date de l'accident, aux cotisations mentionnées à l'article L. 241-5. Si l'utilisatrice est défaillante, l'employeur supporte l'intégralité de ce coût. Le juge peut retenir une répartition différente selon les circonstances de l'espèce.
Ces règles s'appliquent également lorsque l'entreprise utilisatrice est une collectivité, un établissement ou une entreprise autorisés, en vertu des articles L. 413-13 ou L. 413-14, à assumer tout ou partie de la réparation des accidents du travail.
Lorsque le salarié intérimaire agit en responsabilité pour faute inexcusable de l'employeur sans avoir mis en cause l'entreprise utilisatrice, l'entreprise de travail temporaire doit appeler cette dernière en la cause. La même instance statue sur la demande du salarié et sur la garantie des conséquences financières d'une éventuelle reconnaissance de faute inexcusable.
Un décret en Conseil d'Etat fixe les cas et modalités d'application du présent article, notamment la part du coût supportée par l'entreprise utilisatrice et les éléments que les deux entreprises doivent se communiquer à leur demande. Aucun document distinct ni nouvel envoi n'est exigé lorsque les éléments nécessaires figurent dans des pièces exactes et à jour déjà légalement accessibles à l'entreprise qui les demande.
Cette dispense de documents et d'envois redondants s'applique dès l'entrée en vigueur de la loi, y compris aux échanges en cours. Elle ne réduit ni les droits du salarié, ni les garanties, ni les recours relatifs aux accidents et maladies antérieurs. La durée d'une mission ne fixe pas le terme d'un nouveau contrat de travail unique ; les droits attachés aux contrats antérieurs sont préservés.''',
    "Réforme de fond ciblée : suppression des documents et envois entre entreprises faisant double emploi avec des pièces déjà accessibles. Réécriture à droit constant du partage de coût, du recours au juge et de la mise en cause de l'utilisatrice, nécessaires à la réparation des victimes et au contradictoire. Le travail temporaire subsiste comme affectation dans le contrat unique.",
    "Coordonner le décret fixant les échanges documentaires sans supprimer les éléments manquants nécessaires. Les autorisations de L413-13 et L413-14 concernent la prise en charge des accidents et non la rupture d'un salarié protégé. La note source de la loi du 12 juillet 1990 conserve son champ temporel ; elle n'autorise pas de nouveaux CDD ou contrats de mission à terme après la réforme.",
    removed=["Production d'un document distinct ou envoi répété entre entreprises lorsque les éléments utiles existent déjà dans des pièces légalement accessibles."])

add('L241-5-2', '''L'Etat supporte intégralement le coût des accidents du travail et des maladies professionnelles définis aux articles L. 411-1, L. 411-2 et L. 461-1 lorsqu'ils sont imputables au service du salarié dans la réserve sanitaire définie au chapitre II du titre III du livre Ier de la troisième partie du code de la santé publique. Un décret fixe les modalités de cette prise en charge.''',
    "Réécriture à droit constant : l'Etat est désigné comme débiteur de la totalité du coût imputable au service dans la réserve sanitaire. Cette allocation protège le salarié et son employeur ; la retirer créerait une charge au lieu d'en supprimer une. Le renvoi à l'accident de trajet est conservé.",
    "Les trois références L411-1, L411-2 et L461-1 et le chapitre de la réserve sanitaire sont maintenus. La note source fixe l'effet historique au 29 août 2007 ; aucune réforme nouvelle n'est datée de cette publication. Le dispositif ne règle ni la durée d'emploi ni la rupture du contrat.")

add('L241-6', '''Les cotisations, contributions et autres ressources centralisées par la Caisse nationale des allocations familiales couvrent les prestations familiales des salariés et des non-salariés des professions agricoles et non agricoles ainsi que de la population non active. Elles couvrent également leur gestion et leur service, à l'exception de l'allocation de logement familiale prévue au a du 2° de l'article L. 821-1 du code de la construction et de l'habitation. La caisse suit l'exécution de toutes les dépenses.
Les ressources mentionnées au premier alinéa comprennent :
1° Les cotisations assises sur les revenus d'activité des salariés des professions non agricoles et agricoles retenus pour les cotisations définies à l'article L. 242-1. Elles sont intégralement à la charge de l'employeur ;
2° Les cotisations dues par les travailleurs indépendants des professions non agricoles ;
3° Les cotisations dues par les personnes non salariées des professions agricoles ;
4° Une fraction du produit des contributions sociales mentionnées aux articles L. 136-1, L. 136-6, L. 136-7 et L. 136-7-1, dans les conditions fixées à l'article L. 131-8 ;
5° Abrogé ;
6° La taxe exceptionnelle sur les sommes placées sur la réserve de capitalisation des entreprises d'assurance ;
7° Le prélèvement résultant de l'aménagement des règles d'imposition aux prélèvements sociaux de la part en euros des contrats d'assurance vie multisupports ;
8° Le produit des impôts et taxes mentionnés à l'article L. 131-8, dans les conditions fixées par cet article.''',
    "Réécriture à droit constant des charges et des huit rubriques de ressources de la branche famille. La règle d'affectation ne crée pas un fait générateur autonome des taxes citées : la retrancher seule n'allégerait pas leur redevable. Le financement des prestations familiales et l'exclusion de l'allocation logement conservent leur fonction essentielle.",
    "Le L821-1 pertinent est celui du CCH, lu dans le corpus construction-habitation.json : son 2°, a), désigne l'allocation de logement familiale. La cible CSS L821-1 fournie concerne l'AAH et est inapplicable à ce renvoi ; aucune substitution de code. L136-6/7 portent sur les revenus et produits, distincts des droits de succession et de l'IS de la société : ne pas en déduire un impôt sur tout capital transmis par décès. L131-8 proposé garde les affectations des autres revenus. Le caractère historique des ressources des 6° et 7° ne crée aucune taxe exceptionnelle nouvelle.")

add('L241-6-2', '''La Caisse nationale de solidarité pour l'autonomie dispose des ressources suivantes :
1° Les contributions prévues aux articles L. 137-40 et L. 137-41 ;
2° La fraction du produit de la contribution sociale généralisée attribuée dans les conditions de l'article L. 131-8 ;
3° Les produits divers, dons et legs ;
4° Les dotations des autres branches mentionnées à l'article L. 200-2 qui couvrent des dépenses relevant des missions définies à l'article L. 223-5 ;
5° Le produit des astreintes et sanctions financières mentionnées aux II à IV de l'article L. 313-14 du code de l'action sociale et des familles ;
6° Les sommes recouvrées sur le fondement de l'article L. 313-14-3 du même code.''',
    "Réécriture à droit constant de la liste complète des ressources de l'autonomie. Les transferts entre branches, dons et recouvrements ne sont pas des formalités à imposer aux assurés ; les sanctions médico-sociales participent à la protection des personnes accueillies. Aucun prélèvement accessoire autonome n'est ajouté ou supprimé par cette liste d'affectation.",
    "L137-40 et L137-41 ne sont pas la C3S de L137-30. Conserver les dotations affectées aux missions de L223-5 et les récupérations CASF sans les confondre avec un impôt successoral sur les legs reçus. La baisse de CSG privée et sa compensation restent soumises à leur entrée en vigueur financée et à la coordination de L131-8 ; aucun rendement compensateur n'est inventé.")

add('L241-7', '''L'assuré verse à l'employeur sa contribution salariale sur les sommes qu'il reçoit à titre de pourboires, directement ou par l'intermédiaire d'un tiers, sous déduction des sommes déjà précomptées au même titre.
Le seul défaut de ce versement ne constitue pas une cause de rupture du contrat de travail sur le fondement du présent article. Les actions en paiement et les règles applicables aux faits distincts de fraude demeurent ouvertes.
La suppression de cette cause de rupture s'applique aux ruptures notifiées à compter de l'entrée en vigueur de la loi. Les contributions dues pour les périodes antérieures et les recours relatifs aux ruptures déjà notifiées conservent leur régime.''',
    "Réforme de fond : suppression du motif spécial de résiliation pour défaut de remise des cotisations sur pourboires et interdiction d'un second versement de sommes déjà précomptées. Le paiement des cotisations reste assuré ; une dette de cotisation ne justifie pas à elle seule une cause spéciale de perte de l'emploi.",
    "Coordonner les clauses ou règlements reposant exclusivement sur cette cause de résiliation. Les faits distincts de fraude ne sont pas immunisés. Pour le contrat unique, la notification écrite et le préavis individuel de quinze jours restent régis par les textes de rupture ; le présent article ne crée ni rupture automatique, ni dérogation aux procédures collectives ou aux salariés protégés.",
    removed=["Cause spéciale de résiliation du contrat de travail tirée du seul non-versement de la contribution salariale sur les pourboires.", "Second versement à l'employeur de contributions sur pourboires déjà précomptées pour les mêmes sommes."])

add('L241-8', '''L'employeur supporte seul la contribution mise à sa charge. Toute convention qui en transfère la charge est nulle de plein droit.''',
    "Réécriture à droit constant en deux phrases : le débiteur est explicite et la nullité sanctionne le transfert conventionnel de la charge patronale. Cette protection essentielle empêche une baisse du net salarial déguisée ; la supprimer déplacerait la charge vers le salarié.",
    "La nullité reste de plein droit. Cette règle ne transforme pas la prise en charge volontaire d'une part salariale par l'employeur en transfert interdit dans l'autre sens. Elle demeure applicable aux anciens contrats comme aux futurs contrats uniques.")

add('L241-9', '''Le travailleur à domicile rémunéré à façon, aux pièces ou à la tâche, qui est lui-même assuré obligatoire à l'égard du fabricant pour lequel il travaille, ne verse pas les contributions patronales afférentes aux ouvriers qui travaillent avec lui pour ce fabricant. Le fabricant supporte ces contributions, calculées à partir des rémunérations qui lui sont déclarées. Aucune nouvelle déclaration de ces rémunérations ne peut être exigée du travailleur lorsqu'elles figurent déjà dans des données exactes et à jour dont le fabricant dispose légalement.
La rémunération propre au travailleur à domicile est égale à la rémunération globale versée par l'employeur, diminuée des rémunérations des personnes travaillant avec lui et, s'il y a lieu, des frais d'atelier fixés forfaitairement par arrêté ministériel.
La dispense de déclaration redondante s'applique dès l'entrée en vigueur de la loi, y compris aux calculs en cours. Les répartitions de charge et les droits afférents aux rémunérations antérieures demeurent préservés.''',
    "Réforme de fond ciblée : suppression de la nouvelle déclaration au fabricant des rémunérations dont il dispose déjà légalement. Réécriture à droit constant du paiement patronal par le fabricant et du calcul de la rémunération propre, sans faire porter les contributions des ouvriers au travailleur à domicile.",
    "Conserver les deux déductions distinctes : rémunérations des collaborateurs et forfait de frais d'atelier. Le maintien de la déclaration résiduelle pour les données absentes est nécessaire au calcul des droits. La réutilisation n'autorise pas l'accès à des données couvertes par un secret sans fondement légal.",
    removed=["Nouvelle déclaration au fabricant des rémunérations déjà établies par des données exactes et à jour légalement détenues par lui."])

add('L241-12', '''Pour les activités de réinsertion socioprofessionnelle exercées par les personnes en difficulté, les cotisations de sécurité sociale, à l'exception de celles dues au titre des accidents du travail et des maladies professionnelles, sont calculées sur une assiette forfaitaire fixée par arrêté lorsque les rémunérations versées sont inférieures ou égales à cette assiette.
Aucune cotisation patronale de sécurité sociale, sauf au titre des accidents du travail et des maladies professionnelles, n'est due pour ces activités sur l'assiette forfaitaire prévue au premier alinéa ou sur la rémunération, ou la fraction de rémunération, qui n'excède pas, par heure d'activité rémunérée, le salaire minimum de croissance. Cette exonération s'applique aux périodes d'activité accomplies à compter du 1er janvier 1999.
Le présent article s'applique aux personnes accueillies dans les structures suivantes :
– Les centres d'hébergement et de réadaptation sociale visés à l'article L. 345-1 du code de l'action sociale et des familles ainsi que les services ou établissements habilités organisant des activités professionnelles de réinsertion socioprofessionnelle en application des articles L. 121-2 et L. 222-5 du même code ;
– Les structures agréées au titre de l'article 185-2 du même code et de ses textes d'application qui organisent des activités professionnelles d'insertion sociale, ainsi que les structures assimilées inscrites sur la liste fixée par arrêté du ministre chargé de l'action sociale ;
– Les organismes visés à l'article L. 265-1 du même code, sans demande particulière d'admission au bénéfice du présent article.
La suppression de cette demande particulière s'applique aux cotisations dues au titre des périodes d'activité courant à compter de l'entrée en vigueur de la loi, y compris dans les accueils en cours. Les droits, exonérations, restitutions et recours relatifs aux périodes antérieures demeurent soumis aux règles applicables à ces périodes.''',
    "Réforme de fond : accès de plein droit des organismes de L265-1 à l'exonération et à l'assiette prévues, sans demande spéciale de bénéfice. Les trois catégories de structures, l'exclusion AT-MP et le champ historique depuis 1999 sont réécrits à droit constant ; aucune activité de réinsertion future n'est fermée.",
    "Le renvoi source à l'article 185-2 du CASF paraît issu d'une ancienne numérotation ; il est conservé comme anomalie à coordonner sur texte extérieur, sans inventer de concordance ni retirer les structures bénéficiaires. La condition du premier alinéa relative au forfait est reproduite sans inverser silencieusement son inégalité. L'agrément de certaines structures et l'habilitation d'aide sociale ont une fonction de protection distincte de la demande d'exonération supprimée.",
    benefit="L'assiette forfaitaire et l'exonération patronale jusqu'au SMIC horaire restent accessibles pour toutes les futures activités éligibles des trois catégories de structures. Les organismes de L265-1 n'ont plus de demande spéciale à faire. Les droits afférents aux activités depuis le 1er janvier 1999 et leurs recours sont préservés, sans étendre l'exonération aux cotisations AT-MP exclues par la source.",
    removed=["Demande particulière des organismes de L265-1 pour bénéficier des règles d'assiette et d'exonération de réinsertion socioprofessionnelle."])

add('L241-14', '''I. – Les cotisations patronales dues au titre des assurances sociales et des allocations familiales ainsi que les cotisations d'accidents du travail et de maladies professionnelles mentionnées à l'article L. 241-13 sont totalement ou partiellement exonérées dans les conditions du II. L'exonération porte sur les gains et rémunérations définis à l'article L. 242-1 du présent code ou à l'article L. 741-10 du code rural et de la pêche maritime. Elle ne comprend pas les cotisations patronales aux régimes de retraite complémentaire légalement obligatoires.
II. – Pour l'année 2021, cette exonération porte sur les revenus d'activité versés aux salariés mentionnés au 1° et aux 6° à 10° de l'article L. 722-20 du code rural et de la pêche maritime dont l'activité principale relève du secteur de la culture de la vigne mentionné à l'annexe II du décret n° 2020-371 du 30 mars 2020.
Elle s'applique aux cotisations et contributions mentionnées au I qui restent dues après la réduction prévue au I de l'article L. 241-13 du présent code ou toute autre exonération, taux spécifique, assiette forfaitaire ou montant forfaitaire de cotisations. Son montant est égal à :
1° 100 % des sommes restant dues pour les entreprises dont le chiffre d'affaires de 2020 a baissé d'au moins 60 % par rapport à celui de l'année précédente ;
2° 50 % de ces sommes pour les entreprises dont le chiffre d'affaires de 2020 a baissé d'au moins 40 % par rapport à celui de l'année précédente ;
3° 25 % de ces sommes pour les entreprises dont le chiffre d'affaires de 2020 a baissé d'au moins 20 % par rapport à celui de l'année précédente.
Le directeur de l'organisme de recouvrement dont relèvent les travailleurs peut accorder une remise aux employeurs dont l'activité a diminué pendant la période d'activité par rapport à la même période de l'année précédente et qui ne peuvent bénéficier de l'exonération. La remise ne peut dépasser le sixième des sommes dues au titre de l'année 2020.
La réduction d'activité est appréciée selon les modalités fixées par décret pour le fonds de solidarité destiné aux entreprises particulièrement touchées par les conséquences économiques, financières et sociales de la propagation de l'épidémie de covid-19.
III. – Un décret fixe les conditions de mise en œuvre du présent article. Aucune pièce ni déclaration supplémentaire ne peut être exigée pour établir un chiffre d'affaires, une réduction d'activité ou des cotisations que l'organisme de recouvrement peut déjà vérifier à partir de données exactes et à jour dont il dispose ou auxquelles il a légalement accès.
La suppression des productions redondantes s'applique aux demandes et contrôles effectués à compter de l'entrée en vigueur de la loi, y compris pour les périodes anciennes. Les demandes ultérieures demeurent recevables dans les délais qui leur sont applicables ; aucun délai expiré n'est rouvert. Les années 2020 et 2021 et le champ historique de l'avantage ne sont pas modifiés.''',
    "Réforme de fond ciblée : suppression des pièces et déclarations répétant des informations de chiffre d'affaires, d'activité ou de cotisations déjà légalement accessibles au recouvreur. Réécriture complète des trois taux d'exonération et de la remise historique, sans supprimer les créances favorables ni transformer une aide de crise en régime permanent non décidé.",
    "Conserver 2021 pour l'assiette, 2020 pour les baisses de chiffre d'affaires et la remise, les taux 100/50/25 %, les baisses 60/40/20 %, et le plafond d'un sixième. L241-13 est ici une étape d'imputation des cotisations de la période historique, non le barème 2026 appliqué rétroactivement. Les références agricoles et le décret du 30 mars 2020 ont leur champ propre ; aucune conversion de la durée de l'aide en durée d'emploi.",
    benefit="Les exonérations de 100 %, 50 % et 25 % des cotisations restant dues pour 2021 ainsi que la remise plafonnée au sixième des sommes de 2020 sont conservées pour toutes les demandes, restitutions et contestations recevables, y compris futures. Les autres exonérations s'imputent toujours avant ce dispositif. Son objet légal reste la crise de 2020-2021 : ne pas créer de nouvelles années éligibles n'est pas supprimer un avantage futur déjà ouvert par la source.",
    removed=["Production de pièces ou déclarations répétant les données exactes de chiffre d'affaires, d'activité ou de cotisations déjà légalement accessibles au recouvreur."])

add('L241-15', '''Pour appliquer une exonération ou une réduction de cotisations de sécurité sociale prévue par le présent code ou par une autre disposition législative ou réglementaire, l'assiette de calcul comprend toutes les heures rémunérées, quelle que soit leur nature.''',
    "Réécriture à droit constant de la règle transversale d'assiette des allègements. Toutes les heures rémunérées restent prises en compte ; leur retrait diminuerait des exonérations. L'article ne crée ni formalité ni prélèvement distinct à supprimer.",
    "Le champ couvre les exonérations et réductions du code comme celles prévues ailleurs. Ne pas assimiler cette référence aux heures rémunérées au seul travail effectif ni relever implicitement les références annuelles ou conventionnelles lors du passage au contrat unique.",
    benefit="La prise en compte de toutes les heures rémunérées, quelle qu'en soit la nature, demeure pour chaque exonération ou réduction légale ou réglementaire, y compris celles dont les conditions seront remplies à l'avenir. Aucun changement de contrat ou de décompte des heures ne réserve cette règle aux situations antérieures.")

add('L241-16', '''Les sommes versées, au titre de leur activité d'arbitrage ou de jugement, aux arbitres et juges mentionnés au 29° de l'article L. 311-3 qui ne sont pas titulaires d'un contrat de travail sont exonérées des cotisations et contributions de sécurité sociale dans la limite, par année civile, de 14,5 % du montant annuel du plafond mentionné à l'article L. 241-3.
Lorsque le montant annuel de ces sommes dépasse cette limite, seule la fraction excédentaire est soumise aux cotisations et contributions de sécurité sociale. Les remboursements de frais professionnels restent exclus dans les conditions et limites de l'arrêté mentionné au second alinéa du I de l'article L. 136-1-1.
Les fédérations sportives, ou les organes déconcentrés et ligues qu'elles ont créés en application des articles L. 131-11 et L. 132-1 du code du sport, accomplissent les déclarations et versements afférents aux cotisations et contributions mentionnées au deuxième alinéa, dans les conditions fixées par décret.
La suppression de l'assujettissement de la totalité des sommes en cas de dépassement s'applique aux sommes versées au titre des années civiles commençant le 1er janvier de l'année suivant celle de l'entrée en vigueur de la loi. Les années antérieures restent régies par leurs règles, y compris pour les exonérations, remboursements de frais, régularisations, restitutions, prescriptions et recours.''',
    "Réforme de fond : suppression de l'effet de seuil qui réassujettissait la totalité des sommes dès le dépassement de 14,5 % du plafond annuel. La franchise est conservée et seule la fraction supérieure devient cotisable. Réécriture du rôle des fédérations et correction explicite du renvoi aux frais professionnels, devenu inexact dans la source.",
    "Le 29° de L311-3 vise bien l'activité d'arbitre ou juge ; l'absence de contrat de travail demeure. Le troisième alinéa de L242-1 ne désigne plus l'arrêté des frais : la proposition vise le second alinéa du I de L136-1-1, fourni dans reference-targets.json. Ce nouveau renvoi est couvert par un contrôle supplémentaire. Entrée par année civile entière pour ne pas mélanger deux traitements d'un même seuil annuel ; aucun taux de cotisation ni plafond intermédiaire n'est inventé. La réforme ne qualifie pas ces arbitres de salariés privés sous contrat unique.",
    benefit="La franchise annuelle de 14,5 % du plafond reste ouverte à tous les futurs arbitres et juges non titulaires d'un contrat de travail. Elle est renforcée par son maintien après dépassement, alors que la source réassujettissait toutes les sommes. Les remboursements de frais professionnels gardent leur exclusion et les avantages et restitutions des années antérieures restent protégés.",
    removed=["Assujettissement de la fraction jusque-là exonérée des sommes d'arbitrage ou de jugement au seul motif du dépassement de la limite annuelle de 14,5 %."])

add('L241-17', '''I. – Les rémunérations suivantes ouvrent droit à une réduction des cotisations salariales d'origine légale mentionnées à l'article L. 241-3 :
1° Les rémunérations des heures supplémentaires définies aux articles L. 3121-28 à L. 3121-39 du code du travail et, pour les salariés sous convention de forfait annuel en heures prévue au deuxième alinéa de l'article L. 3121-56 du même code, celles des heures effectuées au-delà de 1 607 heures. Pour les nouveaux contrats uniques soumis au seuil hebdomadaire de quarante heures, les rémunérations des heures à temps plein effectuées au-delà de trente-cinq heures et jusqu'à quarante heures par semaine conservent également le bénéfice de la réduction, sans que ces heures deviennent, de ce seul fait, des heures supplémentaires ni ouvrent droit à une majoration légale ;
2° Les rémunérations des heures mentionnées au troisième alinéa de l'article L. 3123-2 du même code ;
3° Les rémunérations des heures supplémentaires mentionnées à l'article L. 3121-41 du même code, sauf celles effectuées en deçà de 1 607 heures lorsque l'accord mentionné à cet article fixe une durée annuelle inférieure à ce niveau ;
4° La majoration versée aux salariés sous convention de forfait annuel en jours prévue à l'article L. 3121-58 du même code, en contrepartie de leur renonciation à des jours de repos dans les conditions de l'article L. 3121-59, au-delà du nombre de jours fixé en application du 3° du I de l'article L. 3121-64 ;
5° Les rémunérations des heures complémentaires des salariés à temps partiel accomplies en application des articles L. 3123-8, L. 3123-9, L. 3123-20 et L. 3123-21, du dernier alinéa de l'article L. 3123-22 et des articles L. 3123-28 et L. 3123-29 du même code ;
6° Les rémunérations des heures supplémentaires accomplies par les salariés des particuliers employeurs ;
7° Les rémunérations des heures supplémentaires accomplies au-delà de quarante-cinq heures par semaine par les assistants maternels définis à l'article L. 421-1 du code de l'action sociale et des familles et celles de leurs heures complémentaires au sens de la convention collective nationale qui leur est applicable ;
8° Les rémunérations des heures supplémentaires ou complémentaires des autres salariés dont la durée du travail ne relève ni du titre II du livre Ier de la troisième partie du code du travail ni du chapitre III du titre Ier du livre VII du code rural et de la pêche maritime. Pour ceux qui relèvent d'un forfait annuel en jours, la réduction porte sur les salaires versés en contrepartie des jours de repos auxquels ils renoncent au-delà de deux cent dix-huit jours.
II. – La réduction est égale au produit d'un taux fixé par décret par les rémunérations mentionnées au I, dans la limite des cotisations d'origine légale et conventionnelle dues par le salarié au titre des heures concernées. Elle s'impute sur les cotisations salariales d'origine légale mentionnées à l'article L. 241-3 dues, pour chaque salarié, sur l'ensemble de sa rémunération définie à l'article L. 242-1 au titre des périodes concernées. Elle ne peut dépasser le montant de ces cotisations.
III. – Les I et II s'appliquent également, selon les modalités fixées par décret :
1° Aux éléments de rémunération versés aux agents publics titulaires et non titulaires pour leurs heures supplémentaires ou leur temps de travail additionnel effectif ;
2° Aux rémunérations des heures supplémentaires ou complémentaires des salariés des régimes spéciaux mentionnés à l'article L. 711-1.
IV. – La réduction s'applique :
1° Aux rémunérations mentionnées au I et à leur majoration, pour cette dernière dans les limites suivantes :
a) Les taux de la convention ou de l'accord collectif applicable mentionné au I de l'article L. 3121-33 du code du travail pour les heures supplémentaires, et à l'article L. 3123-21 ou au dernier alinéa de l'article L. 3123-22 du même code pour les heures complémentaires ;
b) En l'absence de convention ou d'accord applicable :
– Pour les heures supplémentaires, les taux de 25 % ou de 50 % prévus, selon le cas, à l'article L. 3121-36 du même code ;
– Pour les heures complémentaires, les taux de 10 % ou de 25 % prévus, selon le cas, au dernier alinéa de l'article L. 3123-22 ou à l'article L. 3123-29 du même code ;
2° Aux éléments de rémunération mentionnés au 1° du III, dans la limite des dispositions applicables aux agents concernés.
V. – La réduction ne s'applique pas lorsque les salaires ou éléments de rémunération concernés remplacent d'autres éléments de rémunération au sens de l'article L. 242-1. Elle peut toutefois s'appliquer si douze mois au moins séparent le dernier versement de l'élément supprimé en tout ou partie du premier versement des salaires ou éléments de rémunération concernés.
VI. – La réduction peut être cumulée de plein droit avec une exonération totale ou partielle de cotisations salariales de sécurité sociale, des taux réduits, des assiettes forfaitaires ou des montants forfaitaires de cotisations. Ce cumul reste limité par les deux plafonds du II et par les cotisations effectivement dues après application des autres allègements. Il ne requiert pas d'autorisation réglementaire particulière et ne peut donner lieu à un remboursement supérieur aux cotisations dues.
Les allègements nouveaux du 1° du I et du VI s'appliquent aux rémunérations afférentes aux périodes de travail courant à compter de l'entrée en vigueur de la loi. Les droits, créances et recours des périodes antérieures, auxquelles le dispositif s'applique depuis le 1er janvier 2019, sont conservés selon les règles de ces périodes. Une même heure ou rémunération n'est prise en compte qu'une fois. La référence à 1 607 heures, les règles annuelles et les régimes des agents publics, des assistants maternels et des régimes spéciaux ne sont pas relevés au seuil hebdomadaire de quarante heures par le présent article.''',
    "Réforme de fond : suppression de la condition d'autorisation réglementaire du cumul des allègements salariaux, avec maintien des plafonds et du montant réellement dû. La réduction des heures de la 36e à la 40e demeure pour les futurs contrats uniques malgré le nouveau seuil de majoration. Réécriture intégrale des huit catégories, des limites de majoration, du régime public et de la clause anti-substitution à droit constant pour le surplus.",
    "Les 1607 heures des 1° et 3°, les 45 heures des assistants maternels, les 218 jours du 8°, les taux 25/50 % et 10/25 % et le délai anti-substitution de douze mois sont conservés. L3121-34 fourni permet le décompte saisonnier sans CDD : il ne crée pas un terme d'emploi. L3121-36 a été lu en plus dans travail.json : sa proposition maintient 25 % pour huit heures puis 50 %, cohérente avec le IV ; ce renvoi était déjà présent, pas nouvellement inventé. Le financement futur de la retraite ne peut affecter deux fois une même cotisation réduite. Coordonner les décrets de cumul et de calcul, ainsi que L241-18/18-1 pour les heures maintenues au bénéfice social. Aucun régime public ni régime annuel n'est assimilé au nouveau seuil privé.",
    benefit="Les huit catégories de rémunération conservent leur réduction, y compris temps partiel, forfaits, assistants maternels, particuliers employeurs, agents publics et régimes spéciaux. Pour les futurs contrats uniques, le bénéfice social reste ouvert entre 35 et 40 heures sans imposer de majoration salariale nouvelle ; les références annuelles à 1607 heures demeurent. Le cumul devient de plein droit dans les plafonds dus et les droits depuis 2019 ne sont pas réduits.",
    removed=["Condition d'autorisation réglementaire particulière pour cumuler la réduction salariale avec les autres exonérations, taux réduits ou assiettes forfaitaires.", "Perte de la réduction salariale des heures à temps plein de la 36e à la 40e résultant du seul relèvement futur du seuil hebdomadaire des heures supplémentaires."])

add('L241-18', '''I. – Dans les entreprises de moins de vingt salariés, chaque heure supplémentaire effectuée par un salarié mentionné au II de l'article L. 241-13 ouvre droit à une déduction forfaitaire des cotisations patronales dont le montant est fixé par décret.
La déduction s'applique aux heures mentionnées aux 1° à 3° du I de l'article L. 241-17. Elle reste également ouverte, dans les mêmes conditions de montant, aux heures à temps plein effectuées au-delà de trente-cinq heures et jusqu'à quarante heures dans les nouveaux contrats uniques, dont les rémunérations bénéficient de la réduction maintenue au 1° du I de cet article. Cette disposition ne modifie pas la qualification de ces heures pour les majorations de salaire.
II. – Dans ces mêmes entreprises, chaque jour de repos auquel renonce un salarié sous convention de forfait annuel en jours au-delà de deux cent dix-huit jours, plafond mentionné au 3° du I de l'article L. 3121-64 du code du travail, ouvre droit à une déduction égale à sept fois le montant prévu au I. La renonciation intervient dans les conditions de l'article L. 3121-59 du même code.
III. – Pour chaque salarié, les déductions des I et II s'imputent sur les sommes dues par l'employeur aux organismes de recouvrement mentionnés aux articles L. 213-1 du présent code et L. 725-3 du code rural et de la pêche maritime, au titre de l'ensemble de sa rémunération versée lors du paiement de la durée de travail supplémentaire. Elles ne peuvent dépasser ces sommes.
IV. – Les déductions des I et II se cumulent avec les exonérations de cotisations patronales de sécurité sociale, dans la limite des cotisations patronales et des contributions patronales recouvrées selon les mêmes règles qui restent dues sur l'ensemble de la rémunération du salarié.
L'employeur doit respecter les règles légales et conventionnelles de durée du travail. L'heure doit être rémunérée au moins au niveau d'une heure non majorée.
Les déductions ne s'appliquent pas lorsque les revenus d'activité concernés remplacent des sommes soumises à cotisations en application du I de l'article L. 242-1, sauf si douze mois au moins séparent le dernier versement de l'élément supprimé en tout ou partie du premier versement des revenus concernés.
Le bénéfice des déductions reste soumis au règlement (UE) n° 1407/2013 de la Commission du 18 décembre 2013 relatif à l'application des articles 107 et 108 du traité sur le fonctionnement de l'Union européenne aux aides de minimis.
V. – Les agents de contrôle mentionnés à l'article L. 243-7 du présent code et à l'article L. 724-7 du code rural et de la pêche maritime vérifient les déductions à partir des documents et données de paie et de décompte du travail existants. L'employeur met à leur disposition les éléments nécessaires qui leur manquent. Aucun document spécial ni aucune remise répétée de pièces exactes et à jour déjà légalement accessibles ne peut être exigé comme condition du bénéfice des déductions.
V bis. – Abrogé.
VI. – Un décret fixe les modalités d'application du présent article. Il détermine notamment les conditions dans lesquelles les heures supplémentaires des salariés du régime général dont la durée du travail ne relève ni du titre II du livre Ier de la troisième partie du code du travail ni du chapitre III du titre Ier du livre VII du code rural et de la pêche maritime ouvrent droit aux déductions.
Le maintien du bénéfice prévu au deuxième alinéa du I s'applique aux périodes de travail courant à compter de l'entrée en vigueur de la réforme du contrat unique. La suppression du document spécial s'applique aux demandes et contrôles effectués à compter de l'entrée en vigueur de la loi, y compris pour les périodes anciennes, sans reprise d'un document déjà fourni. Les déductions et recours des périodes antérieures sont conservés. Les entreprises bénéficiaires au 31 décembre 2019 conservent l'application des dispositions antérieures dans le champ transitoire du XII de l'article 11 de la loi n° 2019-486 du 22 mai 2019.''',
    "Réforme de fond : suppression du document spécial conditionnant la déduction et des remises en double ; les pièces ordinaires suffisantes servent au contrôle. La déduction reste ouverte aux futures heures de la 36e à la 40e sous contrat unique. L'effectif de moins de vingt, le forfait réglementaire, les sept forfaits par jour, les règles de cumul et l'anti-substitution restent maintenus.",
    "L241-17 fourni est une source officielle seule : son I, 1°, est coordonné dans le présent lot pour préserver 35-40 heures. Les 218 jours, l'imputation URSSAF/MSA, le plafonnement aux sommes dues et la transition des bénéficiaires au 31 décembre 2019 demeurent. Le renvoi source au premier alinéa de L242-1 est rectifié explicitement au I, lequel porte l'assiette et la période ; cette correction ne supprime aucune condition anti-fraude. Le règlement UE1407/2013 cité par la source nécessite une vérification de son champ temporel et de sa concordance avec le cadre européen applicable aux aides nouvelles : référence conservée, aucune conformité européenne présumée ni abrogation nationale de ce cadre. Coordonner les règlements imposant un document exclusif.",
    benefit="La déduction horaire des entreprises de moins de vingt salariés, les sept forfaits par jour au-delà de 218 jours, les cumuls dans les cotisations restantes et la transition des bénéficiaires de 2019 sont conservés. Les futurs contrats uniques gardent l'avantage pour les heures entre 35 et 40, sans nouvelle majoration. Les preuves ordinaires remplacent le document spécial et aucune aide n'est fermée aux futures situations éligibles.",
    removed=["Obligation de constituer un document spécial de contrôle comme condition du bénéfice des déductions forfaitaires patronales.", "Remise répétée de pièces de paie ou de décompte exactes et à jour déjà légalement accessibles aux agents de contrôle.", "Perte du forfait patronal sur les heures de la 36e à la 40e du seul fait du nouveau seuil hebdomadaire du contrat unique."])

add('L241-18-1', '''I. – Dans les entreprises d'au moins vingt salariés, chaque heure supplémentaire effectuée à compter du 1er octobre 2022 par un salarié mentionné au II de l'article L. 241-13 ouvre droit à une déduction forfaitaire des cotisations patronales dont le montant est fixé par décret.
La déduction s'applique aux heures mentionnées aux 1° à 3° du I de l'article L. 241-17. Elle reste également ouverte, dans les mêmes conditions de montant, aux heures à temps plein effectuées au-delà de trente-cinq heures et jusqu'à quarante heures dans les nouveaux contrats uniques, dont les rémunérations bénéficient de la réduction maintenue au 1° du I de cet article. Cette disposition ne modifie pas la qualification de ces heures pour les majorations de salaire.
II. – Dans ces mêmes entreprises, chaque jour de repos auquel renonce un salarié sous convention de forfait annuel en jours au-delà de la limite mentionnée au 3° du I de l'article L. 3121-64 du code du travail ouvre droit à une déduction égale à sept fois le montant prévu au I. La renonciation intervient dans les conditions de l'article L. 3121-59 du même code.
III. – Pour chaque salarié, les déductions des I et II s'imputent sur les sommes dues par l'employeur aux organismes de recouvrement mentionnés aux articles L. 213-1 du présent code et L. 725-3 du code rural et de la pêche maritime, au titre de l'ensemble de sa rémunération versée lors du paiement de la durée de travail supplémentaire. Elles ne peuvent dépasser ces sommes.
IV. – Les déductions des I et II se cumulent avec les exonérations de cotisations patronales de sécurité sociale, dans la limite des cotisations patronales et des contributions patronales recouvrées selon les mêmes règles qui restent dues sur l'ensemble de la rémunération du salarié.
L'employeur doit respecter les règles légales et conventionnelles de durée du travail. L'heure doit être rémunérée au moins au niveau d'une heure non majorée.
Les déductions ne s'appliquent pas lorsque les revenus d'activité concernés remplacent des sommes soumises à cotisations en application du I de l'article L. 242-1, sauf si douze mois au moins séparent le dernier versement de l'élément supprimé en tout ou partie du premier versement des revenus concernés.
Le bénéfice des déductions reste soumis au règlement (UE) n° 1407/2013 de la Commission du 18 décembre 2013 relatif à l'application des articles 107 et 108 du traité sur le fonctionnement de l'Union européenne aux aides de minimis.
V. – Les agents de contrôle mentionnés à l'article L. 243-7 du présent code et à l'article L. 724-7 du code rural et de la pêche maritime vérifient les déductions à partir des documents et données de paie et de décompte du travail existants. L'employeur met à leur disposition les éléments nécessaires qui leur manquent. Aucun document spécial ni aucune remise répétée de pièces exactes et à jour déjà légalement accessibles ne peut être exigé comme condition du bénéfice des déductions.
VI. – Un décret fixe les modalités d'application du présent article. Il détermine notamment les conditions dans lesquelles les heures supplémentaires des salariés du régime général dont la durée du travail ne relève ni du titre II du livre Ier de la troisième partie du code du travail ni du chapitre III du titre Ier du livre VII du code rural et de la pêche maritime ouvrent droit aux déductions.
VII. – Le présent article s'applique à Mayotte et à Saint-Pierre-et-Miquelon.
Le maintien du bénéfice prévu au deuxième alinéa du I s'applique aux périodes de travail courant à compter de l'entrée en vigueur de la réforme du contrat unique. La suppression du document spécial s'applique aux demandes et contrôles effectués à compter de l'entrée en vigueur de la loi, y compris pour les périodes anciennes, sans reprise d'un document déjà fourni. Les droits, déductions et recours antérieurs sont conservés ; l'extension aux entreprises d'au moins vingt salariés résultant de l'article 21 de la loi n° 2025-1403 du 30 décembre 2025 reste applicable aux revenus d'activité des périodes d'emploi courant depuis le 1er janvier 2026.''',
    "Réforme de fond : suppression du document spécial et des doubles remises pour le contrôle de la déduction ; maintien du forfait sur les futures heures entre 35 et 40 sous contrat unique. Réécriture complète du régime d'au moins vingt salariés sans restaurer l'ancienne borne de 250 salariés ni supprimer Mayotte et Saint-Pierre-et-Miquelon.",
    "Conserver l'origine au 1er octobre 2022, le champ d'effectif applicable depuis le 1er janvier 2026, les sept forfaits par jour et le seuil de jours défini par L3121-64, ainsi que les limites de cumul. L241-17 est coordonné dans ce lot ; sa seule source officielle fournie n'intègre pas encore l'extension protectrice 35-40 heures. Le règlement UE1407/2013 cité nécessite, comme pour L241-18, une concordance temporelle avec le cadre européen des aides nouvelles ; aucune suppression d'exigence européenne n'est affirmée. Coordonner les documents réglementaires sans remettre en cause le contrôle de la durée réelle.",
    benefit="La déduction horaire de toutes les entreprises d'au moins vingt salariés et la déduction de sept forfaits par jour restent ouvertes, avec leur application à Mayotte et Saint-Pierre-et-Miquelon et leurs cumuls plafonnés. Les futurs contrats uniques gardent la déduction des heures entre 35 et 40. Les droits des périodes depuis 2022 et l'élargissement applicable depuis 2026 demeurent, sans borne supérieure d'effectif réintroduite.",
    removed=["Obligation de constituer un document spécial de contrôle pour bénéficier de la déduction forfaitaire des entreprises d'au moins vingt salariés.", "Remise répétée de pièces de paie ou de décompte exactes et à jour déjà légalement accessibles aux agents de contrôle.", "Perte du forfait patronal sur les heures de la 36e à la 40e du seul fait du nouveau seuil hebdomadaire du contrat unique."])

add('L241-20', '''L'exonération prévue à l'article L. 241-19 s'applique, dans les mêmes conditions sous réserve des dérogations du présent article, aux revenus d'activité retenus dans l'assiette des cotisations définie à l'article L. 242-1, versés aux salariés embauchés à compter du 1er novembre 2007 par les organismes visés au 1 de l'article 200 du code général des impôts. Ces organismes doivent avoir leur siège social et embaucher les salariés dans les zones de revitalisation rurale définies à l'article 1465 A du même code ou dans les zones France ruralités revitalisation mentionnées aux II et III de son article 44 quindecies A.
Pour cette exonération, les diminutions de 10 % et de 100 % prévues aux deuxième et troisième alinéas du I de l'article L. 241-19 en cas de défaut de négociation sur les salaires ne s'appliquent pas. La condition d'absence de licenciement économique au cours des douze mois précédant l'embauche, prévue au deuxième alinéa du II du même article, ne s'applique pas non plus. Les obligations de négociation et les règles de licenciement ayant un fondement distinct restent applicables.
Les embauches futures sous contrat unique à durée indéterminée restent éligibles. La durée de douze mois de l'exonération n'est ni un terme ni une durée minimale d'emploi. Les contrats à durée déterminée valablement conclus avant la réforme conservent leurs droits à exonération dans les conditions antérieures ; aucun nouveau CDD de droit privé n'est autorisé sur le fondement du présent article.
Les suppressions de conditions prévues au deuxième alinéa s'appliquent aux cotisations dues au titre des périodes d'emploi courant à compter de l'entrée en vigueur de la loi, y compris pour les embauches antérieures dont la période d'exonération n'est pas achevée. Les autres conditions et la durée de l'exonération ne sont pas modifiées. Les droits, créances, restitutions, prescriptions et recours des périodes antérieures demeurent régis par leurs règles.''',
    "Réforme de fond : suppression, pour l'exonération associative rurale, des réductions de 10 % et de 100 % pour défaut de négociation et du blocage de douze mois après un licenciement économique. Ces conditions générales n'établissent pas une fraude dans l'embauche aidée ; les obligations de négociation et les protections contre le licenciement illicite demeurent. Le champ rural, les organismes bénéficiaires et les avantages futurs du contrat unique sont conservés.",
    "Les alinéas de L241-19 visés ont été lus : I, deuxième et troisième alinéas pour les sanctions, II, deuxième alinéa pour le délai après licenciement. Les autres conditions renvoyées, notamment effectif inférieur à cinquante, barème et durée d'exonération de douze mois, demeurent ; aucune durée minimale de contrat unique n'est rétablie. La note du 1er juillet 2024 porte sur les zones FRR et n'est pas une date de réforme future. Une éventuelle suppression générale des mêmes restrictions pour les autres bénéficiaires de L241-19 nécessiterait de reprendre cet article hors du lot ; elle n'est pas prétendue réalisée ici.",
    benefit="L'exonération rurale reste ouverte aux organismes éligibles de l'article 200, 1, du CGI ayant leur siège et leurs embauches dans les zones visées, y compris pour de futures embauches en contrat unique. Ses barèmes, limites et douze mois de bénéfice sont conservés ; les sanctions de négociation et le délai après licenciement sont retirés. Les anciens CDD éligibles et les recours antérieurs ne perdent aucun droit.",
    removed=["Réductions de 10 % puis de 100 % de l'exonération associative rurale pour défaut de négociation sur les salaires, importées du I de L241-19.", "Exclusion de l'exonération associative rurale en raison d'un licenciement économique intervenu dans les douze mois précédant l'embauche."])

add('L242-1', '''I. – Les cotisations de sécurité sociale dues pour l'affiliation au régime général des personnes mentionnées aux articles L. 311-2 et L. 311-3 sont assises sur les revenus d'activité retenus dans l'assiette définie à l'article L. 136-1-1. Elles sont dues au titre des périodes auxquelles ces revenus sont attribués.
II. – Par dérogation au I, les sommes suivantes sont exclues de l'assiette des cotisations de sécurité sociale :
1° Les sommes allouées au salarié au titre de l'intéressement prévu à l'article L. 3312-4 du code du travail ;
2° Les sommes réparties au titre de la réserve spéciale de participation conformément à l'article L. 3324-5 du même code ;
3° Les sommes versées par l'employeur à un plan d'épargne en application de l'article L. 3332-11 du même code et de l'article L. 224-21 du code monétaire et financier ;
4° Les contributions patronales au financement de prestations de protection sociale complémentaire entrant dans le champ des articles L. 911-1 et L. 911-2 du présent code et servies au bénéfice des salariés, anciens salariés et de leurs ayants droit par des institutions de prévoyance, des institutions de gestion de retraite supplémentaire, des mutuelles ou unions pratiquant l'assurance et la capitalisation, des entreprises régies par le code des assurances ou des gestionnaires de plans d'épargne retraite mentionnés à l'article L. 224-8 du code monétaire et financier. Les garanties doivent être obligatoires et collectives pour l'ensemble des salariés ou pour une catégorie de salariés définie selon les critères objectifs fixés par décret en Conseil d'Etat. L'exclusion s'applique :
a) Dans les limites fixées par décret, aux contributions finançant les prestations de retraite supplémentaire déterminées par décret. Pour apprécier ces limites, il est tenu compte de l'abondement patronal à un plan d'épargne pour la retraite collectif exonéré en application de l'article L. 3334-6 du code du travail et à un plan d'épargne retraite d'entreprise exonéré en application du 3° du présent II ;
b) Dans les limites fixées par décret, aux contributions finançant les prestations complémentaires de prévoyance. Lorsque les contributions financent des garanties de frais de santé, ces garanties doivent respecter l'article L. 871-1 du présent code. Le versement patronal mentionné à l'article L. 911-7-1 bénéficie également de l'exclusion d'assiette.
Le présent 4° ne s'applique pas lorsque les contributions patronales remplacent d'autres revenus d'activité soumis à cotisations en application du I et versés au cours des douze derniers mois ;
4° bis Dans les limites fixées par décret, la participation d'un employeur public au financement des garanties d'un contrat collectif de protection sociale complémentaire, lorsqu'elle est obligatoirement versée en application d'un accord prévu au II de l'article 22 bis de la loi n° 83-634 du 13 juillet 1983 portant droits et obligations des fonctionnaires ou de l'arrêté mentionné au II de l'article L. 4123-3 du code de la défense. L'exclusion s'applique si les agents assurés par l'employeur public doivent obligatoirement souscrire à ce contrat ;
5° La contribution de l'employeur d'une entreprise de moins de cinquante salariés à l'acquisition de chèques-vacances, dans les conditions des articles L. 411-9 et L. 411-10 du code du tourisme ;
6° Les avantages mentionnés au I des articles 80 bis et 80 quaterdecies du code général des impôts. L'avantage égal à la différence définie au II de l'article 80 bis du même code entre dans l'assiette prévue au I du présent article lors de la levée de l'option ;
7° Dans la limite de deux fois le montant annuel du plafond défini à l'article L. 241-3 du présent code, les indemnités de rupture du contrat de travail ou de cessation forcée des fonctions de mandataires sociaux, dirigeants et personnes mentionnées à l'article 80 ter du code général des impôts, lorsqu'elles ne sont pas imposables en application de l'article 80 duodecies du même code. Lorsque des indemnités de cessation forcée de fonctions et de rupture du contrat de travail se cumulent, elles sont prises ensemble pour appliquer cette limite. Le dépassement d'un montant de cinq ou de dix fois le plafond annuel n'entraîne plus l'assujettissement de la fraction exclue dans la limite de deux fois ce plafond ; seule la fraction non couverte par l'exclusion demeure assujettie.
Le premier alinéa du présent 7° s'applique aussi aux indemnités mentionnées au 6° de l'article 80 duodecies du code général des impôts versées aux salariés et agents qui peuvent bénéficier d'une pension d'un régime de retraite légalement obligatoire, même si elles sont imposables, dans la limite des montants prévus aux a et b du 6° de cet article.
III. – La suppression, au 7° du II, des assujettissements intégraux liés aux seuils de cinq et de dix fois le plafond annuel s'applique aux indemnités versées au titre des ruptures ou cessations forcées de fonctions intervenant à compter de l'entrée en vigueur de la loi. Les ruptures et cessations antérieures, les exclusions d'assiette, créances, régularisations, restitutions, prescriptions et recours correspondants conservent leur régime. Cette suppression ne modifie ni l'assiette propre de la contribution sociale généralisée ni les droits salariaux et indemnités dus en raison de la rupture.''',
    "Réforme de fond : suppression des trois effets de seuil d'assujettissement intégral des indemnités au-delà de cinq ou dix plafonds annuels, sans enlever la limite d'exclusion de deux plafonds ni la condition fiscale. L'agrégation des indemnités évite le double emploi. Réécriture intégrale à droit constant des autres exclusions, y compris intéressement, participation, épargne, protection complémentaire privée et publique, chèques-vacances et actionnariat.",
    "II, 7° : les seuils de cinq/dix plafonds sont supprimés pour les cotisations seulement ; L136-1-1, III, 5° et 5° bis, fourni, conserve ses seuils CSG tant qu'il n'est pas coordonné explicitement. Ne pas prétendre cette autre charge abolie. L80 ter fourni décrit les personnes visées, sans qualifier leurs mandats de contrats privés. L1234-9 proposé fixe l'indemnité ordinaire des nouveaux contrats : zéro avant un an mesuré au terme avec préavis, puis 0,20 mois par année totale, fractions en mois complets, plafond six mois, employeur seul ; aucun de ces paramètres ne remplace les limites sociales du présent article ni les indemnités spéciales. Le 4° conserve le versement santé de L911-7-1 pour les futures affectations éligibles du contrat unique ; les dispenses et rapports de protection complémentaire ne deviennent pas des conditions d'exclusion nouvelles. Le 4° bis reste propre aux employeurs publics. La note source relative aux opérations réalisées à compter du 15 février 2025 demeure à son objet, distinct de l'entrée en vigueur prospective du nouveau 7°. Les références extérieures, notamment loi de 1983 et CGI80 duodecies, ne sont pas recodifiées sans leur texte intégral.",
    benefit="Les exclusions des 1°, 2°, 3°, 4° a et b, 4° bis, 5°, 6° et 7° demeurent pour les futurs salariés, anciens salariés, ayants droit, agents publics et mandataires éligibles. Les contributions de prévoyance, les dispenses ouvrant le versement santé, les abondements et les chèques-vacances ne perdent aucun avantage. Au 7°, l'exclusion jusqu'à deux plafonds est préservée après dépassement de cinq ou dix plafonds ; l'exception favorable des indemnités de rupture des personnes pouvant prendre leur retraite subsiste, même si elles sont imposables. Les créances anciennes et les indemnités spéciales restent distinctes de l'indemnité ordinaire nouvelle.",
    removed=["Assujettissement intégral des indemnités de cessation forcée de fonctions au seul motif qu'elles dépassent cinq plafonds annuels de sécurité sociale.", "Assujettissement intégral des indemnités de rupture du contrat de travail au seul motif qu'elles dépassent dix plafonds annuels de sécurité sociale.", "Assujettissement intégral des indemnités cumulées de cessation forcée de fonctions et de rupture d'emploi au seul motif du dépassement de cinq plafonds annuels."])

add('L242-1-1', '''Les rémunérations versées ou dues aux salariés et réintégrées dans l'assiette des cotisations après constat d'une des infractions mentionnées aux 1° à 4° de l'article L. 8211-1 du code du travail ne bénéficient d'aucune réduction ou exonération de cotisations de sécurité sociale ni d'aucune minoration de leur assiette.
Cette règle demeure applicable aux contrôles engagés à compter du 1er janvier 2017.''',
    "Réécriture à droit constant de l'exclusion des allègements pour les rémunérations réintégrées après constat des infractions précisément visées. Il s'agit d'une garantie essentielle contre le travail illégal : la suppression subventionnerait les rémunérations dissimulées. Le champ ne s'étend pas aux autres rémunérations de l'employeur.",
    "La restriction porte sur les rémunérations réintégrées et les seules infractions des 1° à 4° de L8211-1, non sur toute erreur déclarative. La date du 1er janvier 2017 vient de la note source et concerne l'engagement du contrôle, non la réforme du contrat unique. Les conditions de défense et le contrôle du juge ne sont pas supprimés.",
    benefit="L'article n'accorde pas une exonération : il écarte les allègements sur les seules rémunérations réintégrées à la suite des infractions des 1° à 4° de L8211-1. Ce mécanisme anti-fraude est maintenu sans extension ; les exonérations attachées aux autres rémunérations et aux futures situations légalement éligibles restent ouvertes.")

add('L242-1-2', '''Pour calculer les cotisations et contributions de sécurité sociale, les rémunérations versées ou dues en contrepartie d'un travail dissimulé au sens des articles L. 8221-3 et L. 8221-5 du code du travail sont, par dérogation à l'article L. 242-1, évaluées forfaitairement à 25 % du plafond annuel défini à l'article L. 241-3, dans sa valeur au jour du constat du délit. Ce forfait s'applique à défaut de preuve contraire portant sur la durée effective de l'emploi et la rémunération versée. Les rémunérations ainsi évaluées relèvent de l'article L. 242-1-1 et sont réputées versées pendant le mois du constat du délit.
Lorsque les faits concernent un particulier employeur mentionné aux 3°, 4° ou 6° de l'article L. 133-5-6, le forfait par salarié est égal à la moitié du plafond retenu au premier alinéa du présent article.
Un décret en Conseil d'Etat fixe les modalités de prise en compte de la rémunération forfaitaire des deux premiers alinéas pour l'ouverture des droits et le calcul des ressources des bénéficiaires des prestations servies par les organismes de sécurité sociale.
Pour apprécier la preuve contraire, l'organisme de recouvrement tient compte des données et pièces exactes et à jour qu'il détient ou auxquelles il a légalement accès ; il ne peut exiger de l'intéressé qu'il les produise à nouveau. Cette dispense de production redondante s'applique dès l'entrée en vigueur de la loi, y compris aux contrôles et recours en cours. Elle ne modifie ni le forfait applicable aux périodes antérieures ni les droits sociaux et voies de recours correspondants.''',
    "Réforme de fond ciblée : retrait de la charge de produire à nouveau les preuves déjà légalement accessibles au recouvreur. Réécriture à droit constant de la présomption réfragable, du forfait de 25 %, du forfait réduit des particuliers et de la prise en compte des droits sociaux. Le mécanisme de reconstitution de la rémunération dissimulée garde sa fonction essentielle anti-fraude.",
    "La moitié du plafond du premier alinéa signifie la moitié du forfait de 25 %, pas 50 % du plafond annuel. La valeur du plafond et le mois réputé de versement sont ceux du constat du délit. L133-5-6, 3°, 4° et 6°, vise emploi domestique, garde d'enfants et aide familiale au pair ; ne pas ajouter les autres catégories du dispositif simplifié. L242-1-1 demeure applicable aux rémunérations reconstituées ; la dispense documentaire n'ouvre pas une exonération de travail dissimulé et ne réduit pas les exigences de preuve sur la durée et la rémunération.",
    benefit="Le forfait réduit de moitié pour les particuliers employeurs des 3°, 4° et 6° de L133-5-6 demeure pour les futures situations concernées. La preuve contraire reste admise sur la durée effective et la rémunération, avec réemploi obligatoire des données disponibles. Les droits sociaux ouverts sur la rémunération reconstituée sont préservés ; ce droit à preuve n'est pas une exonération des rémunérations dissimulées, lesquelles relèvent toujours de L242-1-1.",
    removed=["Nouvelle production à la charge de l'intéressé des preuves exactes de durée d'emploi ou de rémunération déjà légalement accessibles au recouvreur."])

# Chaque appréciation porte sur une vue fournie, et non sur une prétendue validation
# du droit en vigueur. Les empreintes proviennent directement du fichier de vues.
contexts = {
 'L233-1': "la coordination du service aux travailleurs indépendants, sans relation de travail salarié à rompre",
 'L241-2': "les ressources de l'assurance maladie et les remboursements de congés, sans fixation d'une durée d'emploi",
 'L241-3-1': "l'option de cotiser à la vieillesse sur une assiette de temps plein en cas de temps partiel ou de rémunération non horaire",
 'L241-3-2': "le maintien conventionnel de cotisations complémentaires pendant quatre congés qui suspendent l'emploi sans le rompre",
 'L241-3-3': "l'abrogation du malus vieillesse pour défaut de négociation ou de plan d'action sur les salariés expérimentés",
 'L241-5': "le financement des accidents et maladies professionnels, à la charge exclusive de l'employeur",
 'L241-5-1': "le partage du coût AT-MP entre entreprise de travail temporaire et utilisatrice, avec garantie de la victime et contradictoire",
 'L241-6': "l'affectation des ressources aux prestations familiales et l'exclusion de l'allocation de logement familiale du CCH",
 'L241-6-2': "les six catégories de ressources de l'autonomie, sans règle de rupture d'un contrat privé",
 'L241-7': "le versement des contributions sur pourboires et la suppression de la cause spéciale de rupture pour leur seul non-versement",
 'L241-14': "l'exonération de cotisations viticoles de 2021 et les remises rattachées à la crise de 2020, sans nouvelle année d'aide",
 'L241-16': "la franchise des arbitres et juges non titulaires d'un contrat de travail et la suppression de son effet de seuil intégral",
 'L241-17': "les réductions salariales d'heures de travail, avec maintien du bénéfice entre trente-cinq et quarante heures pour les nouveaux contrats",
 'L241-18': "les déductions patronales d'heures et de jours des entreprises de moins de vingt salariés, sans document spécial obligatoire",
 'L241-18-1': "les déductions patronales des entreprises d'au moins vingt salariés, y compris Mayotte et Saint-Pierre-et-Miquelon",
 'L241-20': "l'exonération associative rurale, sa durée de bénéfice de douze mois et l'ouverture aux futurs contrats uniques",
 'L242-1': "l'assiette des cotisations et ses exclusions, notamment les indemnités, la prévoyance privée et la participation des employeurs publics",
 'L242-1-1': "l'exclusion des allègements sur les seules rémunérations réintégrées après constat des infractions de travail illégal visées",
 'L242-1-2': "le forfait réfragable de rémunération dissimulée et sa réduction pour les trois catégories de particuliers employeurs visées",
}

def labour_check(n, target_number):
    intro = f"{n} concerne {contexts[n]}. "
    if target_number == 'L1221-2':
        if n == 'L241-5-1':
            return intro + "La proposition de L1221-2 impose l'emploi privé nouveau à durée indéterminée : la mission de l'intérimaire peut finir, sans fin automatique du contrat. Le partage des risques reste applicable aux missions futures et aux anciens contrats, dont les créances sont préservées. Aucun nouveau CDD n'est rétabli."
        if n == 'L241-20':
            return intro + "L1221-2 proposé ne permet plus de nouveau CDD privé. La période d'exonération de douze mois ne fixe donc ni terme ni durée minimale du contrat unique. L241-19, III, proposé conserve l'accès pour l'accroissement temporaire et les anciens CDD valables ; le présent texte garde ces avantages futurs."
        if n == 'L241-16':
            return intro + "L1221-2 proposé vise les relations de travail relevant du code du travail. Le bénéficiaire ici ne doit précisément pas être titulaire d'un contrat de travail : la franchise n'est pas conditionnée à une conversion en contrat unique et aucune durée de mission ne devient une durée d'emploi."
        return intro + "L1221-2 distingue le CDI de droit commun en vigueur et le contrat unique proposé pour les nouvelles relations privées. Le présent article ne crée aucun recours nouveau au CDD ni terme automatique ; les anciens contrats et les avantages des futures situations éligibles restent dans leur champ, sans extension aux agents publics."
    if target_number == 'L1234-1':
        if n == 'L241-7':
            return intro + "La suppression du motif spécial ne permet pas une rupture immédiate : L1234-1 proposé maintient quinze jours calendaires pour les nouveaux contrats, après notification écrite selon L1234-3. Les anciens contrats conservent leurs durées et anciennetés antérieures ; procédures collectives et autorisations des salariés protégés restent distinctes."
        return intro + "Le préavis de L1234-1 ne règle ni cette assiette ni cette ressource : il ne faut pas lui importer les anciens seuils de six mois/deux ans ou appliquer quinze jours à un agent public. Pour une rupture privée relevant du nouveau régime, les quinze jours se comptent après notification selon L1234-3 ; les procédures collectives et protections restent séparées."
    if target_number == 'L1234-9':
        if n == 'L242-1':
            return intro + "L1234-9 proposé ouvre l'indemnité ordinaire seulement à partir d'un an au terme effectif, préavis inclus : 0,20 mois par année totale, mois complets au prorata, plafond six mois, employeur seul, avec l'exception de faute grave de la vue. Cela ne réduit ni l'exclusion jusqu'à deux PASS des sommes effectivement dues, ni les indemnités spéciales et antérieures ; aucun double calcul d'une période."
        return intro + "L1234-9 proposé n'ajoute pas une condition d'ancienneté à cet article. Son indemnité ordinaire privée est nulle avant un an au terme effectif préavis inclus, puis de 0,20 mois par année totale, fractions en mois complets, plafond six mois, à l'initiative de l'employeur. Les anciens contrats conservent l'ouverture à huit mois et la composante antérieure, sans double période ; réparations et indemnités spéciales restent distinctes."
    raise ValueError(target_number)

target_assessments = {
 '80 ter': "La cible CGI80 ter énumère les dirigeants et personnes fiscalement assimilées visés au II, 7°, de L242-1. Le renvoi identifie ces personnes ; il ne leur attribue pas un contrat de travail privé ni l'indemnité ordinaire du contrat unique. La limite sociale de deux PASS et la condition fiscale de 80 duodecies restent distinctes de la taxation des allocations forfaitaires pour frais décrite par cette cible.",
 'L3121-34': "Le I, 1°, de L241-17 englobe L3121-34 dans la plage L3121-28 à L3121-39. La source exige un accord saisonnier lié à L1244-2 ; sa proposition retire ce support CDD tout en gardant le décompte contradictoire des périodes. Le bénéfice social saisonnier reste possible en contrat unique, sans terme d'emploi ni relèvement automatique des 1607 heures annuelles.",
 'L911-2': "L242-1, II, 4°, renvoie à l'objet des garanties collectives : décès, santé, maternité, incapacité, invalidité, inaptitude, chômage et avantages de retraite restent tous couverts. Le risque décès assuré n'est pas un impôt sur la succession. La suppression de prélèvements successoraux ou d'états administratifs ne ferme ni ces garanties ni leur exclusion d'assiette pour les futures situations éligibles.",
 'L242-1-1': "L242-1-2 maintient le renvoi de ses rémunérations reconstituées à L242-1-1 : les allègements ne s'appliquent pas aux sommes réintégrées après les infractions des 1° à 4° de L8211-1. Le forfait réduit des particuliers et la preuve contraire restent distincts de cette interdiction anti-fraude. La dispense de produire deux fois une preuve n'autorise pas une exonération de travail dissimulé.",
 'L241-17': "Les I de L241-18 et L241-18-1 visent exactement les heures des 1° à 3° du I de L241-17, pas les huit catégories indistinctement. La vue fournie n'est qu'officielle ; la proposition rédigée dans ce lot maintient aussi les heures à temps plein entre 35 et 40 pour les nouveaux contrats uniques. Les deux déductions patronales sont expressément coordonnées avec cette extension, sans changer les 1607 heures des régimes annuels.",
 'L241-5': "L241-5-1 fait supporter une partie du coût AT-MP à l'utilisatrice si elle relève des cotisations de L241-5 à la date de l'accident ; l'employeur reste garant en cas de défaillance. La proposition de L241-5 dans le lot conserve charge exclusivement patronale, assiette de L242-1 et réductions plafonnées. Cette référence ne fixe ni terme d'une mission ni ancienneté de rupture.",
 'L911-7-1': "L242-1, II, 4°, b), garde l'exclusion d'assiette du versement santé patronal de L911-7-1. La proposition de cette cible conserve les futurs bénéficiaires en contrat unique pendant les affectations ou périodes temporaires éligibles, avec couverture responsable, non-cumul et garanties collectives existantes. La fin de l'affectation ne rompt pas l'emploi et ne ferme pas par elle-même cet avantage.",
 'L862-4': "L241-2, IV, 8°, vise la taxe des contrats du II de L862-4, et non tous les cas du II bis. La cible fixe le taux général de 13,27 %, ses conditions de solidarité, sa majoration et des taux réduits ou exonérations distincts. Le texte d'affectation ne les modifie pas ; il ne crée ni nouvelle taxe ni condition d'ancienneté. Le renvoi à L131-8 doit utiliser sa règle d'affectation réelle.",
 'L133-5-6': "L242-1-2, deuxième alinéa, vise seulement les 3°, 4° et 6° de L133-5-6 : particuliers employeurs de salariés domestiques, garde d'enfants et stagiaires aides familiaux au pair. Le forfait réduit n'est pas étendu aux autres utilisateurs du dispositif déclaratif simplifié. Ces qualités ne dispensent pas de prouver la durée et la rémunération pour écarter la présomption ; aucun terme d'emploi privé n'en découle.",
 'L213-1': "Pour L233-1, L213-1 désigne les organismes de recouvrement participant au service des indépendants ; pour L241-18 et L241-18-1, il désigne les organismes d'imputation des déductions. La proposition fournie de L213-1 retire les redondances, prévoit l'extinction conditionnée de C3S et celle du CPF-CDD futur. Aucun de ces renvois ne recrée un prélèvement supprimé ou une obligation documentaire équivalente.",
 'L223-5': "L241-6-2, 4°, affecte des dotations aux dépenses relevant des missions de L223-5 : soutien à l'autonomie, équité territoriale, prévention, offre médico-sociale, information, recherche et métiers. La cible proposée retire la collecte répétée de données déjà disponibles, pas les prestations ni leur financement. Cette affectation ne renvoie ni à l'ancienneté d'un emploi ni au préavis du contrat privé.",
 'L136-6': "L241-6, 4°, vise la CSG sur les revenus du patrimoine de L136-6, distincte de la CSG salariale privée proposée à 6,6 %. Les exemptions d'affiliation européenne, l'absence de double contribution et le seuil de non-recouvrement de 61 euros de la cible restent dans leur champ. Le renvoi d'affectation ne convertit pas ces revenus en salaire, ni la fiscalité personnelle en IS à la distribution ou en droit de succession.",
 'L311-3': "Pour L241-16, le renvoi est exclusivement au 29° de L311-3, qui affilie les arbitres et juges pour cette activité même sans contrat de travail. Pour L242-1, la cible délimite les personnes assimilées au régime général, dont des mandataires et des catégories autonomes. L'affiliation sociale n'établit pas par elle-même un contrat privé et ne leur impose ni conversion en contrat unique ni condition d'ancienneté nouvelle.",
 'L241-10': "L241-5, deuxième alinéa, conserve l'imputation de la réduction du III de L241-10 sur l'AT-MP au taux minimal plafonné. La proposition de la cible maintient les aides à domicile en contrat unique, les anciens CDD éligibles et les CDD de droit public de remplacement selon leur régime. L241-5 ne retire aucune de ces exonérations futures et garde la seconde phrase portant l'arrêté au même emplacement.",
 'L241-3': "La cible L241-3 porte le plafond annuel, les cotisations vieillesse et, dans sa seule proposition, un transfert progressif vers la capitalisation. Le plafond non décroissant et les cotisations effectivement dues restent les références du présent article. Le transfert proposé commence seulement après financement et coordinations préalables, dans son champ salarié privé ; il ne relève pas automatiquement les assiettes non horaires, les forfaits ou les régimes publics et ne permet aucun double emploi de cotisation.",
 'L623-1': "L241-2 finance la maternité et les autres prestations ; L623-1 détaille celles des indépendants, avec leurs interruptions d'activité, allocations, indemnités, adoption, deuil et mandats locaux. La note QPC du 8 août 2025 conserve le bénéfice pour la femme dont la filiation est établie par reconnaissance conjointe dans le cas indiqué. Ces périodes d'indemnisation ne sont ni une durée d'emploi privé ni un préavis ; aucun avantage n'est retranché par l'affectation.",
 'L331-8': "L331-8 porte les indemnités de paternité et d'accueil : vingt-cinq jours, trente-deux en naissance multiple, cessation minimale de quatre jours et hospitalisation, avec régime de l'élu local. L241-2 assure leur financement sans changer leur durée ni les non-cumuls. Aucun renvoi au préavis individuel de quinze jours ne peut réduire ces congés ou transformer leur fin en fin du contrat unique.",
 'L223-1': "L241-2, IV, 2°, vise précisément L223-1, 6° : 60 % pour certaines indemnités, totalité pour les catégories visées aux b et d et frais de gestion aux mêmes proportions. La proposition de L223-1 simplifie les missions administratives sans réduire ces remboursements et conserve la transition naissance 2026. Ces taux sont des répartitions de financement et non un barème de cotisations ou de rupture d'emploi.",
 'L241-13': "La cible L241-13 fixe le champ et le calcul de la réduction générale : les déductions de L241-18/18-1 s'y réfèrent au II et se cumulent dans les limites dues ; L241-5 conserve l'imputation AT-MP et L241-14 son ordre d'imputation historique. La proposition fournie préserve le calcul distinct plus favorable des affectations temporaires du contrat unique sans terme d'emploi ni double période. Les taux et seuils nouveaux ne sont pas appliqués rétroactivement aux rémunérations de 2021.",
 'L242-1': "La cible fournie L242-1 est officielle seule. Son I définit les revenus d'activité et leur période, son II maintient les exclusions. Dans le présent lot, l'assiette générale et les avantages des II, 1° à 6°, restent et le 7° retire seulement les effets de seuil d'assujettissement intégral des indemnités. Les renvois d'assiette n'importent ni un seuil d'ancienneté ni une rupture automatique ; ils ne rétablissent pas les charges retirées.",
 'L136-1-1': "Le I de L136-1-1 fournit l'assiette des revenus d'activité et son second alinéa l'exclusion des frais professionnels : il sert à L242-1, I, et corrige le renvoi périmé de L241-16. Le III, 2°, b), vise les retraites complémentaires pour L241-3-2, dont le d) exclut la part salariale prise en charge dans ses conditions. La CSG et ses seuils d'indemnités gardent leur champ distinct des cotisations ; ni contrat unique ni suppression d'états annuels ne suppriment ces exclusions.",
 'L131-8': "L131-8 définit les affectations de taxes et de CSG ; ses 3°, 8° et 9° sont notamment pertinents pour maladie, famille et autonomie. Sa proposition coordonne la baisse financée de CSG salariale privée à 6,6 % par répartition proportionnelle et compensation, sans appliquer ce taux au patrimoine ni aux pensions. Le renvoi ne doit créer ni recette fictive ni taxe de remplacement. Au 8°, la source fournie ne mentionne pas l'arrêté que L241-2 citait : cette incohérence est corrigée explicitement.",
 'L136-7': "L241-6, 4°, affecte une fraction de la CSG de placement de L136-7. Le II, 3°, de la cible taxe les produits des contrats et évite leur double prise en compte, pas l'ensemble du capital transmis ; III et III bis préservent les restitutions, et I ter la dispense européenne. Le renvoi de ressources ne rétablit pas de droits de succession ou d'IS annuel et ne confond pas cette assiette avec les seuls salaires privés à 6,6 %.",
 'L241-19': "L241-20 reprend l'exonération rurale de L241-19, dont le III proposé ouvre douze mois de bénéfice au contrat unique sans durée minimale d'emploi et conserve les anciens CDD éligibles. Le présent lot déroge expressément aux deuxième et troisième alinéas du I (diminutions 10/100 %) et au deuxième alinéa du II (douze mois sans licenciement). Les autres conditions de zone, de barème, d'effectif et de cumul restent renvoyées à la cible, sans prétendre l'avoir réécrite pour tous ses bénéficiaires.",
 'L821-1': "La cible fournie est CSS L821-1 et règle l'allocation aux adultes handicapés, ses conditions de résidence, ses prestations différentielles et ses droits lors du passage à la retraite. Elle ne correspond pas au renvoi de L241-6, qui cite expressément le CCH L821-1, 2°, a), sur l'allocation de logement familiale. Ce dernier a été lu dans le corpus CCH. Aucune condition de l'AAH ni ancienneté de contrat privé n'est importée par cette fausse homonymie.",
}

specific_checks = {
 ('L233-1','L213-1'): "Le renvoi de L233-1 à L213-1 identifie les unions de recouvrement participant au service des indépendants. La proposition fournie de L213-1 maintient le recouvrement et l'action sociale et supprime les demandes répétées de données. Retirer le schéma et son approbation ne retire aucune mission de ces unions ni aucun droit futur ouvert par les cotisations ; la suppression conditionnée de C3S reste à son calendrier propre.",
 ('L241-18','L213-1'): "Le III de L241-18 vise les unions de L213-1 comme organismes d'imputation, à côté de la MSA de L725-3 rural. La proposition fournie réemploie les données et ne permet pas de réclamer une seconde correction identique. Le V proposé de L241-18 est cohérent : pièces ordinaires et éléments manquants suffisent, sans document spécial ni suppression de la dette résiduelle ou du contrôle.",
 ('L241-18-1','L213-1'): "Le III de L241-18-1 vise les unions de L213-1 pour imputer les forfaits des entreprises d'au moins vingt salariés ; les sommes dues sont le plafond d'imputation. La proposition fournie de L213-1 supprime les demandes redondantes sans changer cette compétence. Le V proposé utilise les pièces existantes, y compris dans le champ territorial du VII, et ne crée pas de nouvelle déclaration de remplacement.",
 ('L241-3-1','L241-3'): "La dérogation à L241-3 permet de conserver volontairement l'assiette vieillesse à temps plein malgré le temps partiel ou une rémunération non horaire. La proposition de L241-3 organise aussi un transfert futur de cotisations effectivement dues, conditionné au financement et aux coordinations. Elle ne transforme pas l'option de surcotisation en obligation ni le salaire fictif de temps plein en nouvelle assiette générale de transfert.",
 ('L241-3-2','L241-3'): "L241-3-2 déroge à l'organisation des cotisations de L241-3 pour permettre des versements complémentaires pendant quatre congés. La capitalisation ajoutée dans la proposition de L241-3 a un premier champ privé et des préalables non déclarés remplis. Elle ne supprime ni la retraite complémentaire conventionnelle ni l'exclusion de CSG élargie ici ; aucun même versement ne peut être affecté deux fois.",
 ('L241-16','L241-3'): "Le renvoi à L241-3 sert uniquement à déterminer le plafond annuel dont 14,5 % fixent la franchise d'arbitrage. La proposition de L241-3 conserve le plafond annuellement fixé et non décroissant ; son transfert futur de cotisations ne concerne pas automatiquement les arbitres sans contrat de travail. Le seuil annuel reste entier, et seul l'excédent devient cotisable pour les nouvelles années visées.",
 ('L241-17','L241-3'): "Les I et II de L241-17 identifient les cotisations salariales légales de vieillesse de L241-3 comme support de la réduction et de son imputation sur toute la rémunération. La proposition de L241-3 ne met en œuvre un transfert que sur des cotisations effectivement dues après ses préalables financés. Une cotisation déjà effacée par la réduction ne finance ni deux droits ni un transfert supplémentaire.",
 ('L242-1','L241-3'): "Le II, 7°, de L242-1 utilise le plafond annuel de L241-3 pour limiter l'exclusion à deux PASS. La proposition conserve ce plafond non décroissant ; elle ne confond pas ce seuil social avec six mois de salaire de l'indemnité ordinaire. Les anciens seuils de cinq et dix PASS sont retirés pour les cotisations dans ce lot, mais pas implicitement pour la CSG régie séparément.",
 ('L242-1-2','L241-3'): "Le premier alinéa de L242-1-2 retient 25 % du plafond annuel de L241-3 dans sa valeur au constat du travail dissimulé. Le deuxième alinéa divise par deux ce forfait pour les seuls particuliers visés. Le plafond demeure fixé annuellement et non décroissant dans la proposition de L241-3 ; le transfert futur à la capitalisation ne modifie ni la date de valeur ni la présomption réfragable.",
 ('L241-3-2','L136-1-1'): "Le b du 2° du III de L136-1-1 identifie les régimes complémentaires auxquels les versements de congé peuvent être destinés ; le d du même 2° exclut la part salariale prise en charge dans les conditions de L241-3-2. Ce dernier retirant ici la limite de six mois pour les périodes futures, le renvoi du d suit l'extension sans nouvelle attestation ni application aux seules situations anciennes.",
 ('L241-16','L136-1-1'): "Le second alinéa du I de L136-1-1 décrit les frais professionnels exclus et l'arrêté des ministres de la sécurité sociale et du budget. Il remplace explicitement dans L241-16 le troisième alinéa de L242-1 devenu inexact. Cette cible est fournie et son I maintenu dans la proposition ; les remboursements continuent d'être exclus selon les conditions et limites de l'arrêté, sans perte lors du dépassement de la franchise d'arbitrage.",
 ('L242-1','L136-1-1'): "Le I de L242-1 reprend l'assiette d'activité de L136-1-1, dont le I exclut notamment les frais professionnels. Le II de L242-1 conserve ensuite ses exclusions propres : il ne faut pas importer automatiquement les seuils CSG du III, 5° et 5° bis, de L136-1-1 dans le nouveau 7°. L'abandon des effets de seuil pour les cotisations ne prétend pas supprimer ceux de cette CSG distincte.",
 ('L241-16','L311-3'): "Le 29° de L311-3 affilie les arbitres et juges pour leur activité d'arbitrage ou de jugement ; c'est la seule catégorie visée par L241-16. La franchise reste limitée aux personnes non titulaires d'un contrat de travail. Cette affiliation ne vaut pas contrat privé et la réforme du contrat unique ne peut fermer la franchise aux futurs arbitres ou leur imposer un an d'ancienneté.",
 ('L242-1','L311-3'): "L242-1, I, vise l'ensemble des personnes assimilées au régime général par L311-3, y compris mandataires, arbitres et autres catégories sans contrat salarié. Le renvoi d'assiette demeure général ; il n'autorise pas à leur appliquer automatiquement le contrat unique, son préavis de quinze jours ou son indemnité. Les abattements et options de la cible ont leur propre champ et ne sont pas supprimés ici.",
 ('L241-5','L241-13'): "L241-13, I, permet l'imputation de la réduction générale sur l'AT-MP au taux fixé par la seconde phrase du deuxième alinéa de L241-5. Cette phrase reste à cet emplacement dans la proposition, avec le plafond du risque minimal. La cible proposée conserve l'avantage des futures affectations sous contrat unique ; aucune suppression de l'allègement ou exonération AT-MP totale n'est introduite par la coordination.",
 ('L241-14','L241-13'): "L241-14 applique l'exonération viticole après la réduction de L241-13 et les autres allègements, sur le reliquat dû de 2021. Le barème actuel 2026 de la cible fournie ne peut être appliqué rétroactivement à ce calcul historique. La proposition de L241-13 conserve les avantages des affectations du contrat unique, ce qui ne crée ni nouvelle année viticole éligible ni double imputation.",
 ('L241-18','L241-13'): "Le I de L241-18 vise précisément les salariés du II de L241-13, avec les exclusions et catégories qui y figurent. Le VI de cette cible autorise le cumul avec le forfait de L241-18. Sa proposition maintient le calcul favorable des affectations temporaires sous contrat unique ; le forfait ne dépend donc pas de la survie d'un nouveau CDD et reste plafonné aux cotisations restant dues.",
 ('L241-18-1','L241-13'): "Le I de L241-18-1 vise les salariés du II de L241-13 ; aucune ancienne borne de 250 salariés n'est rétablie par ce renvoi. Le VI de la cible permet le cumul avec L241-18-1, dans les limites dues. La proposition préserve les calculs favorables de missions et formations du contrat unique sans terme d'emploi, et les coordinations du présent lot gardent les heures entre 35 et 40 au bénéfice du forfait.",
 ('L241-2','L131-8'): "L241-2, IV, 1°, 3°, 8° et 9°, renvoie aux affectations de L131-8, notamment au b du 3° pour la maladie et au 8° pour les contrats complémentaires. Le 8° fourni ne mentionne pas l'arrêté cité par L241-2 : ce renvoi erroné est explicitement remplacé par la subdivision elle-même. La baisse de CSG privée financée dans la proposition de L131-8 ne modifie ni les autres revenus ni les prestations financées.",
 ('L241-6','L131-8'): "Les 4° et 8° de L241-6 attribuent à la famille les fractions de CSG et les produits définis par L131-8, dont le 3°, a). Sa proposition distingue la baisse privée à 6,6 % financée et les autres revenus, avec répartition proportionnelle et compensation. Le renvoi de L241-6 ne change pas lui-même ces taux et ne crée ni nouvelle taxe sur le capital ni recette compensatrice fictive.",
 ('L241-6-2','L131-8'): "L241-6-2, 2°, vise la fraction de CSG de l'autonomie attribuée par L131-8, notamment son 3°, f), et ses rubriques propres aux autres revenus. La proposition de L131-8 coordonne seulement la baisse privée financée par une répartition et une compensation distinctes. Le financement de l'autonomie ne peut être réduit silencieusement ni reconstitué par un taux non décidé ; les autres cotisations restent à leur champ.",
 ('L241-5','L242-1'): "Le premier alinéa de L241-5 reprend l'assiette d'activité de L242-1 pour l'AT-MP. Dans le présent lot, le I et les exclusions du II de L242-1 sont réécrits et les effets de seuil de son 7° sont retirés pour les faits nouveaux. Le renvoi ne doit pas réintégrer les sommes légalement exclues ni transférer au salarié la charge patronale exclusive d'AT-MP.",
 ('L241-6','L242-1'): "L241-6, 1°, utilise l'assiette de L242-1 pour les cotisations patronales familiales des salariés agricoles et non agricoles. Le I de la cible porte les revenus d'activité ; son II conserve les exclusions, dont la proposition du lot retire seulement les effets de seuil des indemnités. Cette référence d'assiette n'applique ni la réforme du contrat privé aux indépendants ni le taux de CSG salariale aux cotisations familiales.",
 ('L241-14','L242-1'): "L241-14, I, vise L242-1 pour les gains et rémunérations non agricoles, à côté du renvoi rural distinct. La cible donnée est une version actuelle ; pour les exonérations et remises de 2021 et 2020, les règles temporelles d'assiette restent celles de ces périodes. La nouvelle suppression des effets de seuil d'indemnités n'est pas appliquée rétroactivement à l'exonération viticole.",
 ('L241-16','L242-1'): "Le deuxième alinéa de L241-16 citait l'arrêté du troisième alinéa de L242-1, mais la version fournie place à cet endroit le II, 1°, sur l'intéressement. Le renvoi était donc déjà inexact. Il est explicitement remplacé par le second alinéa du I de L136-1-1, qui contient bien les frais professionnels et l'arrêté ; leur exclusion est maintenue et la nouvelle cible fournie est contrôlée séparément.",
 ('L241-17','L242-1'): "L241-17, II, impute la réduction sur les cotisations vieillesse de l'ensemble de la rémunération de L242-1 et son V utilise cette assiette pour empêcher une substitution artificielle de salaire. Le I de la cible demeure le fondement des revenus et périodes ; ses exclusions ne sont pas effacées. La suppression du filtre réglementaire de cumul reste plafonnée aux cotisations effectivement dues après les autres allègements.",
 ('L241-18','L242-1'): "Le IV de L241-18 renvoie à l'assiette des sommes remplacées pour sa clause anti-substitution de douze mois. La source disait premier alinéa de L242-1 ; la proposition vise expressément le I, qui contient bien cette définition dans la vue fournie. L'effet anti-fraude et le délai sont conservés ; les exclusions du II ne sont pas supprimées et aucun nouveau régime de rupture n'est importé.",
 ('L241-18-1','L242-1'): "Le IV de L241-18-1 vise le I de L242-1 pour interdire la substitution de revenus d'activité cotisables aux sommes ouvrant le forfait, sous l'exception des douze mois. Le renvoi est déjà correct dans la source et reste inchangé. Les exclusions de la cible, dont le nouveau 7° rédigé dans ce lot, gardent leur effet ; la dispense de document spécial ne supprime pas ce contrôle anti-substitution.",
 ('L241-20','L242-1'): "L241-20 vise les revenus d'activité entrant dans l'assiette de L242-1, I, et non une assiette forfaitaire inventée à partir du nombre de mois aidés. Les exclusions du II demeurent. Les sanctions de négociation et le délai post-licenciement supprimés ici sont des conditions d'accès importées de L241-19, pas une extension d'assiette des cotisations ou une durée minimale du contrat unique.",
 ('L242-1-2','L242-1'): "L242-1-2 déroge à l'assiette de L242-1 seulement pour évaluer une rémunération dissimulée faute de preuve contraire sur l'emploi et le salaire. La proposition conserve le forfait et le mois du constat ; elle réemploie seulement les preuves disponibles. Cette dérogation ne permet ni de requalifier toute erreur en travail dissimulé ni d'effacer les exclusions ordinaires hors du champ de la reconstitution.",
}

for s in sources:
    n = s['number']
    a = answers[n]
    keys = list(refs['requirements'].get(s['code_id']+'|'+s['source_id'], []))
    if n == 'L241-16':
        # Cible déjà fournie ; contrôle du renvoi corrigé aux frais professionnels.
        k = next(k for k,t in refs['targets'].items() if t['number']=='L136-1-1')
        if k not in keys:
            keys.append(k)
    checks = []
    for k in keys:
        t = refs['targets'][k]
        tn = t['number']
        assessment = ("Contrôle transversal, sans renvoi textuel direct. " + labour_check(n, tn)
                      if tn in ('L1221-2','L1234-1','L1234-9')
                      else specific_checks.get((n,tn), f"{n} concerne {contexts[n]}. " + target_assessments[tn]))
        checks.append(dict(target_key=k, view_sha256=t['view_sha256'], assessment=assessment))
    a['reference_checks'] = checks

# Rectifications explicites constatées en confrontant les vues intégrales.
a = answers['L241-2']
a['proposed_xml'] = a['proposed_xml'].replace("dans les conditions fixées par l'arrêté mentionné au 8° de l'article L. 131-8", "dans les conditions fixées au 8° de l'article L. 131-8")
a['reason'] += " Le renvoi à un arrêté absent du 8° de L131-8 est expressément rectifié vers la règle d'affectation effectivement fournie."
a['review_notes'] += " Incohérence préexistante : le IV, 8°, cite un arrêté qui n'apparaît pas au 8° de L131-8 fourni. La correction rédactionnelle vise directement cette subdivision sans inventer un arrêté ni modifier son affectation."
a = answers['L241-6']
a['proposed_xml'] = a['proposed_xml'].replace("ainsi que de la population non active. Elles couvrent également leur gestion et leur service, à l'exception de l'allocation de logement familiale prévue au a du 2° de l'article L. 821-1 du code de la construction et de l'habitation.", "ainsi que de la population non active, à l'exception de l'allocation de logement familiale prévue au a du 2° de l'article L. 821-1 du code de la construction et de l'habitation. Elles couvrent également la gestion et le service de ces prestations.")
for n in ['L241-17','L241-18','L241-18-1']:
    answers[n]['removed_provisions'] = [p for p in answers[n]['removed_provisions'] if not p.startswith('Perte ')]

Path('answer.json').write_text(json.dumps([answers[s['number']] for s in sources], ensure_ascii=False, indent=2)+'\n')
